<script setup lang="ts">
import type { components } from '~/api/schema'; import { displayError } from '~/utils/errors';
type Address = components['schemas']['Address']; type AddressWrite = components['schemas']['AddressWrite'];
definePageMeta({ middleware: 'auth' }); const addressApi = useAddresses(); const appAlert = useAppAlert(); const editing = ref<Address | null>(null); const showForm = ref(false); const message = ref('');
const form = reactive<AddressWrite>({ label: '', recipient_name: '', phone: '', street: '', province: '', city: '', district: '', postal_code: '', is_default: false });
onMounted(() => { void addressApi.load().catch(() => undefined); });
function reset() { Object.assign(form, { label: '', recipient_name: '', phone: '', street: '', province: '', city: '', district: '', postal_code: '', area_id: undefined, latitude: undefined, longitude: undefined, is_default: false }); editing.value = null; showForm.value = false; message.value = ''; }
function edit(address: Address) { editing.value = address; Object.assign(form, { label: address.label ?? '', recipient_name: address.recipient_name, phone: address.phone, street: address.street, province: address.province ?? '', city: address.city ?? '', district: address.district ?? '', postal_code: address.postal_code, area_id: address.area_id, latitude: address.latitude, longitude: address.longitude, is_default: address.is_default ?? false }); showForm.value = true; window.scrollTo({ top: 0, behavior: 'smooth' }); }
async function save() { message.value = ''; if (!/^\d{5}$/.test(form.postal_code)) { message.value = 'Kode pos harus terdiri dari 5 angka.'; return; } if ((form.latitude === undefined) !== (form.longitude === undefined)) { message.value = 'Latitude dan longitude harus diisi bersama.'; return; } try { if (editing.value) await addressApi.update(editing.value, { ...form }); else await addressApi.create({ ...form }); reset(); } catch (cause) { message.value = displayError(cause).message; } }
async function archive(address: Address) { const confirmed = await appAlert.confirmAction({ title: `Arsipkan ${address.label || 'alamat ini'}?`, text: 'Alamat akan dihapus dari pilihan pengiriman berikutnya.', confirmText: 'Ya, arsipkan', danger: true }); if (!confirmed) return; try { await addressApi.archive(address); await appAlert.success({ title: 'Alamat diarsipkan' }); } catch (cause) { message.value = displayError(cause).message; await appAlert.error({ title: 'Alamat gagal diarsipkan', text: message.value }); } }
function masked(phone: string) { return phone.length < 7 ? phone : `${phone.slice(0,3)}••••${phone.slice(-3)}`; }
useSeoMeta({ title: 'Alamat — Niaga' });
</script>
<template><main id="main-content" class="page-shell"><BuyerNav/><div class="section-heading"><div><p class="eyebrow">Buku alamat</p><h1>Alamat pengiriman</h1></div><button type="button" @click="showForm = !showForm">{{ showForm ? 'Tutup editor' : 'Tambah alamat' }}</button></div><form v-if="showForm" class="surface address-form" @submit.prevent="save"><h2>{{ editing ? 'Edit alamat' : 'Alamat baru' }}</h2><label class="form-field">Label<input v-model.trim="form.label" required maxlength="150" placeholder="Rumah / Kantor"></label><label class="form-field">Nama penerima<input v-model.trim="form.recipient_name" required maxlength="150"></label><label class="form-field">Nomor telepon<input v-model.trim="form.phone" required maxlength="32" inputmode="tel"></label><label class="form-field form-span">Alamat lengkap<textarea v-model.trim="form.street" required maxlength="2000" rows="4"/></label><label class="form-field">Provinsi<input v-model.trim="form.province" required maxlength="150"></label><label class="form-field">Kota/Kabupaten<input v-model.trim="form.city" required maxlength="150"></label><label class="form-field">Kecamatan<input v-model.trim="form.district" required maxlength="150"></label><label class="form-field">Kode pos<input v-model.trim="form.postal_code" required pattern="[0-9]{5}" maxlength="5" inputmode="numeric"></label><label class="form-field">Area ID pengiriman<input v-model.trim="form.area_id" placeholder="Opsional bila koordinat tersedia"></label><label class="form-field">Latitude<input v-model.number="form.latitude" type="number" min="-90" max="90" step="any"></label><label class="form-field">Longitude<input v-model.number="form.longitude" type="number" min="-180" max="180" step="any"></label><label class="checkbox"><input v-model="form.is_default" type="checkbox">Jadikan alamat utama</label><p v-if="message" class="error form-span" role="alert">{{ message }}</p><div class="form-actions form-span"><button :disabled="addressApi.pending.value" type="submit">{{ addressApi.pending.value ? 'Menyimpan…' : 'Simpan alamat' }}</button><button class="button--secondary" type="button" @click="reset">Batal</button></div></form><ApiState :pending="addressApi.pending.value && !addressApi.addresses.value.length" :error="addressApi.error.value ? displayError(addressApi.error.value) : null" :empty="!showForm && !addressApi.pending.value && !addressApi.addresses.value.length" empty-title="Belum ada alamat" empty-message="Tambahkan alamat untuk menghitung ongkir dan membuat RFQ." @retry="addressApi.load"><template #action><button type="button" @click="showForm = true">Tambah alamat</button></template><div class="address-grid"><article v-for="address in addressApi.addresses.value" :key="address.id" class="surface address-card"><div class="section-heading"><h2>{{ address.label || 'Alamat' }}</h2><span v-if="address.is_default" class="badge">Utama</span></div><strong>{{ address.recipient_name }}</strong><p>{{ masked(address.phone) }}</p><p class="muted">{{ address.street }}<br>{{ address.district }}, {{ address.city }}, {{ address.province }} {{ address.postal_code }}</p><div class="form-actions"><button class="button--secondary" type="button" @click="edit(address)">Edit</button><button class="text-button" type="button" @click="archive(address)">Arsipkan</button></div></article></div></ApiState></main></template>
